css:
.fx-sf{width:min(1040px,100%);display:grid;gap:2.4em}
.fx-sf .top{max-width:34em;display:grid;gap:.6em}.fx-sf h2{font-size:clamp(1.8em,4vw,2.7em)}.fx-sf .top p{opacity:.68}
.fx-sf ol{--g:1.8em;list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--g)}
.fx-sf li{position:relative;display:grid;gap:.5em;align-content:start;outline:none;padding-top:.2em}
.fx-sf .n{width:3em;height:3em;border-radius:50%;display:grid;place-items:center;font:600 1em var(--font-heading);border:1.5px solid var(--primary);color:var(--primary);background:var(--surface);transition:background calc(.3s/var(--speed)),color calc(.3s/var(--speed)),transform calc(.3s/var(--speed));margin-bottom:.7em}
.fx-sf li:hover .n,.fx-sf li:focus-visible .n{background:var(--primary);color:var(--on-primary);transform:scale(1.08)}
.fx-sf li:focus-visible .n{outline:2px solid var(--accent);outline-offset:3px}
.fx-sf li::after{content:"";position:absolute;top:1.7em;left:3.5em;right:calc(-1*var(--g) + .5em);height:0;border-top:1.5px dashed var(--accent);transform-origin:left;animation:fxsfdraw calc(.7s/var(--speed)) ease both;animation-delay:calc(var(--i)*.55s/var(--speed))}
.fx-sf li:last-child::after{display:none}
.fx-sf li:nth-child(1){--i:1}.fx-sf li:nth-child(2){--i:2}.fx-sf li:nth-child(3){--i:3}
.fx-sf h3{font-size:1.2em}.fx-sf li p{opacity:.7;font-size:.93em}
.fx-sf em{font-style:normal;justify-self:start;margin-top:.4em;padding:.2em .7em;border-radius:99px;font-size:.76em;font-weight:700;background:color-mix(in srgb,var(--accent) 16%,transparent)}
@keyframes fxsfdraw{from{transform:scaleX(0)}to{transform:none}}
@media(max-width:760px){.fx-sf ol{grid-template-columns:1fr;--g:1.6em}
.fx-sf li{padding-left:4.3em;min-height:5em}.fx-sf .n{position:absolute;left:0;top:0}
.fx-sf li::after{top:3.6em;bottom:calc(-1*var(--g) + .5em);left:1.5em;right:auto;width:0;height:auto;border-top:0;border-left:1.5px dashed var(--accent);transform-origin:top;animation-name:fxsfdrawy}}
@keyframes fxsfdrawy{from{transform:scaleY(0)}to{transform:none}}
@media(prefers-reduced-motion:reduce){.fx-sf li::after{animation:none}.fx-sf .n{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-sf li.is-tap .n{background:var(--primary);color:var(--on-primary);transform:scale(1.08)}
